#if TEST_BUILD
using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed partial class ControlWindow {
 internal async Task RunDailyFlowSmoke(){try{
  int originalCount=library.Doc.Items.Count;string sound=Common.Json.Serialize(settings);var confirmations=library.Doc.Items.ToDictionary(x=>x.Id,x=>String.Join("|",x.RegisteredSha256,x.PreviewConfirmedSha256,x.DesktopConfirmedSha256,x.PreviewConfirmationRun,x.DesktopVerificationRun));
  Require(CurrentRun==null&&!LoginRestore.IsEnabled(new WindowsStartupStore()),"Autoplay or startup enabled");ClientShot(this,"daily-flow-home");
  OpenLocalImport();await WaitCoverDialog();Require(importDialog.list.Items.Count>0&&CurrentRun==null,"Static import scan");foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="317495"){row.Selected=true;row.EnsureVisible();break;}await Task.Delay(150);ClientShot(importDialog,"daily-flow-static-import");await importDialog.ImportSelected();Require(library.Doc.Items.Count==originalCount&&CurrentRun==null,"Duplicate import autoplay/card duplication");importDialog.Close();
  SelectWallpaper(library.Doc.Items.Single(x=>x.Id=="builtin-317495"));await StartMode("desktop");await WaitOfflineState("mounted");await Task.Delay(700);RememberRestoreTarget();Require(File.Exists(LoginRestore.TargetPath),"Restore target not saved");int pid=player.Pid;long created=player.Creation;string run=CurrentRun;long heartbeat=Convert.ToInt64(Common.Read(Path.Combine(run,"ui-heartbeat.json"))["sequence"]);
  await HideAndKeepPlaying();await Task.Delay(1400);Require(!Visible&&PlayerRole=="alive"&&player.Pid==pid&&Convert.ToInt64(Common.Read(Path.Combine(run,"ui-heartbeat.json"))["sequence"])>heartbeat,"Hidden controller stopped playback/heartbeat");
  // A different executable under the same user cannot issue the show command.
  string intruder=Path.Combine(Common.Root,"tests/bin/ChannelIntruder.exe");using(var bad=Process.Start(new ProcessStartInfo(intruder,Common.Quote(Application.ExecutablePath)){UseShellExecute=false,CreateNoWindow=true})){bool ended=await Task.Run(()=>bad.WaitForExit(6000));Require(ended&&bad.ExitCode==0&&!Visible,"Wrong-image client activated interface");}
  await ReopenSameEntry();Require(Visible&&CurrentRun==run&&player.Pid==pid&&player.Creation==created,"Reopen overlapped or switched playback");ClientShot(this,"daily-flow-reopened");
  Require(Common.Json.Serialize(settings)==sound,"Sound changed across hide/reopen");await StopManaged("daily-flow-stop");Require(Clean,"Stop not clean");
  // Same restore handler; startup trigger is simulated, never a registry write or a login claim.
  restoreTask=RestoreLastWallpaper();await restoreTask;await WaitOfflineState("mounted");await Task.Delay(500);Require(activeRunRequest!=null&&Common.S(activeRunRequest,"selectedCatalogId")=="builtin-317495"&&Common.S(activeRunRequest,"expectedSha256")==Common.CwpHash,"Restore picked a different source");
  foreach(var x in library.Doc.Items)Require(confirmations[x.Id]==String.Join("|",x.RegisteredSha256,x.PreviewConfirmedSha256,x.DesktopConfirmedSha256,x.PreviewConfirmationRun,x.DesktopVerificationRun),"Confirmation changed");Require(Common.Json.Serialize(settings)==sound,"Sound changed after restore");
  Common.SaveNew(Path.Combine(Common.Root,"evidence/daily-flow-passed.json"),new{cards=originalCount,staticImport=true,duplicateImport=true,noAutoPlaybackOnImport=true,explicitHideContinuesSamePlayer=true,hiddenHeartbeatContinues=true,wrongImageClientRejected=true,reopenReturnsSameController=true,stopClean=true,restoreExactManagedTarget=true,restoreTrigger="internal handler; simulated authorized launch, no Windows login/startup write",settingsPreserved=true,confirmationsPreserved=true,closeWhilePlaying=true,method="internal TEST_BUILD handlers; not user clicks",runToClose=CurrentRun});Close();
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence/daily-flow-failed.json"),new{error=ex.ToString()});Write("daily-flow-test-failed",new{error=ex.ToString()});}if(!closing){await StopManaged("daily-flow-test-failed");Close();}}
 async Task ReopenSameEntry(){using(var next=Process.Start(new ProcessStartInfo(Application.ExecutablePath){UseShellExecute=false})){bool ended=await Task.Run(()=>next.WaitForExit(7000));Require(ended&&next.ExitCode==0,"Reopen did not acknowledge existing UI");}}
}
#endif
